import std.io

pub type AppError = Failed(String)

pub fn main() effect io -> Result<(), AppError> {
    let xs = [1, 2, 3]
    let it = xs.iterator().map(|x| x * 2)
    let jt = xs.iterator().map(|x| x * 2)
    let b = it.all(|x| x > 0)
    if b { io.println("all-ok") } else { io.println("all-bad") }

    let n = jt.all(|x| x > 2)
    if n { io.println("all-miss-bad") } else { io.println("all-miss-ok") }

    return Ok(())
}
